    "id": "revisao-dirigente-indemnizacao-pressupostos",
    "law": "dirigente",
    "topic": "Cargos dirigentes: regime nacional",
    "subtopic": "Indemnização",
    "familyId": "dirigente:revisao-indemnizacao-pressupostos",
    "conceptId": "dirigente:revisao-indemnizacao-pressupostos",
    "region": "Nacional",
    "professionalArea": "Recursos Humanos",
    "administrationScopes": [
      "central"
    ],
    "difficulty": 4,
    "prompt": "Uma cessação por reorganização ocorre após oito meses seguidos de exercício. Só por esse facto há direito à indemnização do art. 26.º?",
